 {section==='leads'&&!leadId&&<section className="panel lead-list"><div className="filters"><div className="search-field"><Search size={17}/><input aria-label="Search leads" value={query} placeholder="Search people, companies, email…" onChange={e=>setFilter('q',e.target.value)}/></div><select aria-label="Filter by stage" value={stageFilter} onChange={e=>setFilter('stage',e.target.value)}><option value="">All stages</option>{stages.map(s=><option key={s}>{s}</option>)}</select><select aria-label="Filter by assignee" value={assignedFilter} onChange={e=>setFilter('assignee',e.target.value)}><option value="">All assignees</option>{members.map(m=><option key={m.user_id} value={m.user_id}>{m.name}</option>)}</select><label className="check-label"><input type="checkbox" checked={archived} onChange={e=>setFilter('archived',e.target.checked?'1':'')}/> Archived</label></div><div className="lead-table"><div className="table-head"><span>NAME / COMPANY</span><span>STAGE</span><span>DEAL VALUE · USD</span><span>ASSIGNEE</span><span>NEXT FOLLOW-UP</span></div>{pageLeads.map(l=>{const next=tasks.filter(t=>t.lead_id===l.id&&!t.completed).sort((a,b)=>a.due_at.localeCompare(b.due_at))[0];return <article className="lead-table-row" key={l.id}><Link href={href('/leads/'+l.id)}><span className="avatar">{initials(l.name)}</span><span><strong>{l.name}</strong><small>{l.company||'No company'}</small></span></Link><div>{stageSelect(l)}</div><strong>{money(Number(l.value))}</strong><span className="assignee-cell"><span className="tiny-avatar">{initials(person(l.assignee_id))}</span>{person(l.assignee_id)}</span><span className={next&&new Date(next.due_at).getTime()<Date.now()?'late':''}>{next?date(next.due_at):'No follow-up'}<Link className="icon-button" href={href('/leads/'+l.id)} aria-label={`View ${l.name}`}><ChevronRight size={15}/></Link></span></article>;})}</div>{!filtered.length&&<Empty title="No leads in this view.">Try another filter or add your first lead.</Empty>}<div className="pagination"><span>{filtered.length} leads · Page {page} of {Math.max(1,Math.ceil(filtered.length/10))}</span><div><button aria-label="Previous page" disabled={page<=1} onClick={()=>setFilter('page',String(page-1))}><ChevronLeft size={16}/></button><button aria-label="Next page" disabled={page*10>=filtered.length} onClick={()=>setFilter('page',String(page+1))}><ChevronRight size={16}/></button></div></div></section>}
